pub struct Icons;

impl AssetSource for Icons {
    fn load(&self, path: &str) -> gpui::Result<Option<Cow<'static, [u8]>>> {
        if path == "logo.svg" {
            return Ok(Some(Cow::Borrowed(include_bytes!("../assets/logo.svg"))));
        }
        Ok(ICONS.iter().find(|(name, _)| *name == path).map(|(_, body)| {
            let svg = format!(r##"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#000" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{body}</svg>"##);
            Cow::Owned(svg.into_bytes())
        }))
    }

    fn list(&self, _: &str) -> gpui::Result<Vec<SharedString>> {
        Ok(ICONS.iter().map(|(name, _)| SharedString::from(*name)).collect())
    }
}

/// 16px 用于列表、按钮、菜单，20px 用于工具栏和播放器
pub fn icon(name: &'static str, size: f32, color: impl Into<Hsla>) -> Svg {
    svg().path(name).size(px(size)).flex_none().text_color(color)
}

#[cfg(test)]
mod tests {
    #[test]
    fn every_icon_loads_as_svg() {
        use gpui::AssetSource;
        for (name, _) in super::ICONS {
            let bytes = super::Icons.load(name).unwrap().expect(name);
            assert!(bytes.starts_with(b"<svg"));
        }
        assert!(super::Icons.load("nope").unwrap().is_none());
    }
}
